const allowedDomains = ['akademiata.edu.pl', 'wseiz.edu.pl', 'gmail.com'];

return items.map((item) => {
  const fromValue = item.json.from || item.json.headers?.from || '';

let fromRaw = '';

if (typeof fromValue === 'string') {
  fromRaw = fromValue;
} else if (fromValue?.text) {
  fromRaw = fromValue.text;
} else if (fromValue?.html) {
  fromRaw = fromValue.html;
} else if (Array.isArray(fromValue?.value) && fromValue.value[0]?.address) {
  fromRaw = fromValue.value[0].address;
} else {
  fromRaw = JSON.stringify(fromValue);
}

const allowedDomains = ['akademiata.edu.pl', 'wseiz.edu.pl'];
const emailMatch = String(fromRaw).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const senderEmail = emailMatch ? emailMatch[0].toLowerCase() : '';
const senderDomain = senderEmail.split('@')[1] || '';
const isAllowedDomain = allowedDomains.includes(senderDomain);

  const subject = item.json.subject || '';
  const textPlain = item.json.textPlain || item.json.text || item.json.snippet || '';
  const html = item.json.textHtml || item.json.html || '';
  const emailBody = textPlain || html || item.json.snippet || '';

  return {
    json: {
      ...item.json,
      senderEmail,
      senderDomain,
      isAllowedDomain,
      subject,
      emailBody,
      threadId: item.json.threadId,
      messageId: item.json.id || item.json.messageId
    },
    binary: item.binary
  };
});

return items.map((item) => {
  console.log(`Ignored email from disallowed domain: ${item.json.senderEmail}`);
  return item;
});

const items = $input.all();

function getFirstJson(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

const gmail = getFirstJson('Gmail Trigger');
const extracted = getFirstJson('Extract Email Context');

return items.map((item) => {
  const content = item.json.message?.content || item.json.content || {};

  const rawIntent =
    content.intent ||
    item.json.intent ||
    'other';

  const reason =
    content.reason ||
    item.json.reason ||
    '';

  let intent =
    String(rawIntent).trim().toLowerCase() === 'approval_request'
      ? 'approval_request'
      : 'other';

  const emailText = [
    gmail.subject,
    gmail.textPlain,
    gmail.text,
    gmail.body,
    gmail.snippet,
    extracted.subject,
    extracted.emailSubject,
    extracted.textPlain,
    extracted.text,
    extracted.body,
    extracted.snippet,
    extracted.emailText,
    extracted.message,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  const clearlyOtherTopic =
    emailText.includes('ders programı') ||
    emailText.includes('ders programi') ||
    emailText.includes('class schedule') ||
    emailText.includes('timetable') ||
    emailText.includes('lesson schedule') ||
    emailText.includes('course schedule') ||
    emailText.includes('exam schedule') ||
    emailText.includes('lecture schedule') ||
    emailText.includes('where can i find the timetable') ||
    emailText.includes('where i can find the timetable');

  if (clearlyOtherTopic) {
    intent = 'other';
  }

  return {
    json: {
      ...item.json,
      intent,
      isApprovalRequest: intent === 'approval_request',
      reason: clearlyOtherTopic
        ? 'Clearly about class schedule/timetable, not internship application approval.'
        : String(reason),
    },
    binary: item.binary,
  };
});

return items.map((item) => {
  console.log(`No reply sent. Email is not an internship approval request. Sender: ${item.json.senderEmail}`);
  return item;
});

return items.map((item, index) => {
  let binary = item.binary || {};

  // Groq/OpenAI node binary veriyi düşürdüyse Gmail Trigger'dan geri al
  if (!binary || Object.keys(binary).length === 0) {
    const gmailItems = $items('Gmail Trigger');
    binary = gmailItems[index]?.binary || gmailItems[0]?.binary || {};
  }

  const binaryKeys = Object.keys(binary);

  let pdfBinaryKey = null;

  for (const key of binaryKeys) {
    const data = binary[key] || {};
    const fileName = String(data.fileName || '').toLowerCase();
    const mimeType = String(data.mimeType || '').toLowerCase();
    const fileExtension = String(data.fileExtension || '').toLowerCase();

    if (
      mimeType === 'application/pdf' ||
      fileExtension === 'pdf' ||
      fileName.endsWith('.pdf')
    ) {
      pdfBinaryKey = key;
      break;
    }
  }

  return {
    json: {
      ...item.json,
      hasPdfAttachment: Boolean(pdfBinaryKey),
      pdfBinaryKey,
    },
    binary,
  };
});

return items.map((item) => {
  const pdfBinaryKey = item.json.pdfBinaryKey;

  if (!pdfBinaryKey || !item.binary?.[pdfBinaryKey]) {
    throw new Error('PDF binary key is missing.');
  }

  item.binary.pdf = item.binary[pdfBinaryKey];

  return item;
});

const item = $input.first();

const pdfBinary =
  item.binary?.pdf ||
  item.binary?.attachment_0 ||
  Object.values(item.binary || {}).find((file) => {
    return (
      String(file.mimeType || '').toLowerCase() === 'application/pdf' ||
      String(file.fileExtension || '').toLowerCase() === 'pdf' ||
      String(file.fileName || '').toLowerCase().endsWith('.pdf')
    );
  });

const signatureBinary = item.binary?.signature_image;

if (!pdfBinary) {
  throw new Error('PDF binary bulunamadı.');
}

if (!signatureBinary) {
  throw new Error('signature_image binary bulunamadı.');
}

return [
  {
    json: {
      ...item.json,
      pdfBinaryKey: 'pdf',
      signatureImageBinaryKey: 'signature_image',
    },
    binary: {
      pdf: pdfBinary,
      signature_image: signatureBinary,
    },
  },
];

const items = $input.all();

const signatureBase64 = ``;

return items.map((item) => {
  return {
    json: {
      ...item.json,
    },
    binary: {
      ...item.binary,
      signature_image: {
        data: signatureBase64,
        mimeType: 'image/png',
        fileName: 'signature.png',
        fileExtension: 'png',
      },
    },
  };
});
